  'chelp.e2.q': 'वस्तू कशी शोधायची?',
  'chelp.e2.a': 'वरचा सर्च बार वापरा, किंवा श्रेणींमध्ये पाहा. बोलून शोधण्यासाठी 🎤 माइक दाबा आणि वस्तूचे नाव बोला.',
  'chelp.e3.q': 'ऑर्डर कशी करायची?',
  'chelp.e3.a': 'दुकान उघडा, हव्या त्या वस्तू कार्टमध्ये टाका, स्वतः घेऊन जाणे की डिलिव्हरी निवडा, आणि ऑर्डर करा दाबा. दुकानाला तुमची ऑर्डर मिळते आणि ते ती निश्चित करतात.',
  'chelp.e4.q': 'स्वतः घेऊन जाणे आणि डिलिव्हरीत काय फरक आहे?',
  'chelp.e4.a': 'स्वतः घेऊन जाणे म्हणजे तुम्ही ऑर्डर स्वतः दुकानातून आणता, मोफत. डिलिव्हरी म्हणजे दुकान तुमच्यापर्यंत पोहोचवते, कधी थोड्या शुल्कासह — बरीच दुकाने ठरलेल्या रकमेच्या वर मोफत डिलिव्हरी देतात.',
  'chelp.e5.q': 'ऑर्डरचे पैसे कसे भरायचे?',
  'chelp.e5.a': 'तुम्ही खात्यावर (उधार), ऑनलाइन, किंवा रोख भरू शकता. खात्यावर घेतले तर ती रक्कम त्या दुकानातल्या तुमच्या चालू शिल्लकीत जमा होते, नंतर फेडता येते.',
  'chelp.e6.q': 'माझे खाते (उधार) कसे चालते?',
  'chelp.e6.a': 'तुमचे खाते प्रत्येक दुकानातली तुमची उधारी एका ठिकाणी दाखवते. प्रत्येक खरेदी आणि भरणा नोंदला जातो, त्यामुळे तुमची शिल्लक नेहमी माहीत असते आणि तपशील पाहता किंवा डाउनलोड करता येतो.',
  'chelp.e7.q': 'माझी ऑर्डर कशी ट्रॅक करायची?',
  'chelp.e7.a': 'ऑर्डर टॅब उघडा आणि प्रत्येक ऑर्डर प्रलंबित पासून स्वीकारले, मग तयार किंवा पूर्ण होताना पाहा. प्रत्येक टप्प्यावर तुम्हाला अपडेट मिळते.',
