  // No native Gujarati speaker has read any of it. It ships because the
  // alternative was an English screen in front of a Gujarati-speaking
  // shopper, and plain, unreviewed Gujarati beats that — but treat every
  // line as provisional until a reviewer signs it off. The review sheet is
  // docs/i18n-review-consumer-indo-aryan.md, generated from these exact values
  // and ordered worst-first: money, khata and order strings sit at the top of
  // it, because those are the ones that cost a shopper money when they are wrong.
  //
  // Where the same English already had a Gujarati translation elsewhere in
  // this repo — the owner dictionary (mobile-app/src/i18n.js) or the shipped
  // catalogue — that wording was reused verbatim rather than re-invented, so the
  // shopper and the shopkeeper read the same words about the same order.
  //
  // 'upd.runtime' and 'upd.channel' are deliberately absent and fall back to en.
  // They label the two Expo build tokens on the update card, whose VALUES are
  // themselves English identifiers; a transliterated label beside one of those
  // would read as noise, so no translation is better than a bad one.
